<?php $flagged=array_filter($content_quality['courses']??array(),function($r){return !empty($r['flags']);});$moderation=$content_quality['moderation']??array();?>
<div class="row"><div class="col-12"><div class="card"><div class="card-body"><h4 class="page-title">Content Quality & Moderation</h4><p class="text-muted mb-0">Course readiness, accessibility, moderation turnaround, and actionable quality gaps.</p></div></div></div></div>
<div class="row"><div class="col-md-3"><div class="card"><div class="card-body"><small>Courses tracked</small><h3><?php echo count($content_quality['courses']??array());?></h3></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Quality flags</small><h3><?php echo count($flagged);?></h3></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Moderation turnaround</small><h3><?php echo $moderation['average_hours']!==null?$moderation['average_hours'].'h':'No data';?></h3></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Within 72 hours</small><h3><?php echo (float)($moderation['within_72_percent']??0);?>%</h3><span><?php echo (int)($moderation['pending']??0);?> pending</span></div></div></div></div>
<div class="row"><div class="col-12"><div class="card"><div class="card-body"><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Course</th><th>Teacher</th><th>Lifecycle</th><th>Lessons</th><th>Accessibility</th><th>Quality gaps</th><th></th></tr></thead><tbody><?php foreach(($content_quality['courses']??array()) as $row):?><tr><td><?php echo html_escape($row['title']);?></td><td><?php echo html_escape(trim($row['first_name'].' '.$row['last_name']));?></td><td><?php echo html_escape(ucwords(str_replace('_',' ',$row['workflow_status'])));?></td><td><?php echo (int)$row['lessons'];?></td><td><?php echo number_format((float)$row['accessibility_score'],1);?>%</td><td><?php foreach($row['flags'] as $flag):?><span class="badge badge-warning mr-1"><?php echo html_escape($flag);?></span><?php endforeach;?><?php if(!$row['flags']):?><span class="text-success">No current flags</span><?php endif;?></td><td><a class="btn btn-outline-primary btn-sm" href="<?php echo site_url('admin/course_form/course_edit/'.$row['id']);?>">Review</a></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div>
